-- Replace the sample (fictional) doctors with real doctors listed in public Egyptian
-- medical directories for Kafr El Sheikh, Bila, Hamoul, Riyadh, Qallin and Baltim.
--
-- Sources are recorded per row in the "source" column. Names and addresses were copied from the
-- listing pages; phone numbers / prices are filled ONLY where the page showed them (otherwise NULL).
-- Some listing pages truncate addresses, so a few show street name + town only.
-- "verified = true" here means "listed in a public directory and approved for display" - it is NOT
-- an independent check. Call the clinic before relying on a row.
--
-- Run in Supabase SQL Editor after 20261011000000_seed_catalog.sql. Safe to re-run.

alter table public.providers add column if not exists badge  text;
alter table public.providers add column if not exists source text;

-- remove the fictional sample doctors (labs/pharmacies/etc. are untouched)
delete from public.providers where slug like 'dr-%' or name like 'د. نورا%';

on conflict (name, area) do update set
  slug = excluded.slug, specialty = excluded.specialty, specialty_id = excluded.specialty_id,
  address = excluded.address, phone = excluded.phone, whatsapp = excluded.whatsapp, price = excluded.price,
  is_featured = excluded.is_featured, active = true, verified = true, badge = excluded.badge, source = excluded.source;
